-- Canon and playbook for Depot > Analytics > Guide tabs (Sean, 2026-10-31: "update the canon and playbook for the Guide tabs view").
update public.knowledge_records
set version = 3, updated_by = 'logan', updated_at = now(),
    change_summary = 'Depot view of the Guide tab numbers built and live 2026-10-31 (Logan): Depot > Analytics > Guide tabs.',
    body = body || jsonb_build_object(
      'tracking_built', 've_promo_events, promo gt-<guide slug>, steps view and click, cta tab, with the listing. Read in Depot > Analytics > Guide tabs (#guidetabs): the page''s period against the one before, By Guide (saw it, before, change, clicked, click rate, listings it showed on) and By listing (the listing, its Guide, saw it, clicked, click rate), people counted once each; ve_guide_tab_stats(from, to, prev_from, prev_to), service role only, through ve-analytics guide_tabs. Also ve_promo_funnel. Bots, demo pages and LESARUSS.ai are not counted; counting started 2026-10-31.',
      'depot_view', 'Built and live 2026-10-31 (Sean: "build the Depot view for the Guide tab numbers"), merged to main at 463b43d; ve-analytics deployed from 4d84aac (source sha256 matched). Checked live with two test events (a view and a click on Love Life Cafe, returned correctly, then removed) and drawn on desktop and phone.')
where slug = 'canon-ve-listing-guide-tab' and version < 3;

insert into public.playbook_records (slug, brand_slug, author, body, source, kind)
select 've-listing-guide-tab', 'vegans-explore', 'Logan',
  'BUILD RECORD, 2026-10-31 (Logan): the Depot view of the Guide tab numbers. Sean: "build the Depot view for the Guide tab numbers". Depot > Analytics has a Guide tabs tab (#guidetabs, admin/depot/analytics.html) on the page''s own period picker, against the period before. By Guide: how many people saw each Guide''s tab, before, change, how many clicked Open the Guide, click rate, how many listings it showed on. By listing: each listing (opening its Guide tab), its Guide, saw it, clicked, click rate; searchable and sortable. People are counted once each; bots, demo pages and LESARUSS.ai are not counted. Data: ve_guide_tab_stats(from, to, prev_from, prev_to) over ve_promo_events where promo starts gt- and cta is tab (migration 20261031_guide_tab_stats.sql, security definer, service role only), returned by ve-analytics as guide_tabs. Live: the function applied, ve-analytics deployed from commit 4d84aac with its source sha256 matching the repo, main at 463b43d. Proven with two test events on Love Life Cafe (returned as 1 view and 1 click on the Dairy Guide), removed through the one-time ve-once-guide-tab (now the 410 stub); the tab drawn on desktop and at 390 px with no errors or sideways scroll. Counting started 2026-10-31, so the numbers grow from zero.',
  'text', 'decision'
where not exists (select 1 from public.playbook_records where slug = 've-listing-guide-tab' and body like 'BUILD RECORD, 2026-10-31 (Logan): the Depot view%');
